{"explanation":"Compare the value with the lower and upper bounds, returning the appropriate bound when outside the interval and the original value otherwise. This preserves finite numeric inputs and does not mutate anything.","code":"function solve(value, lower, upper) {
  if (value < lower) return lower;
  if (value > upper) return upper;
  return value;
}"}

{"explanation":"Use a local numeric variable so the input is not mutated. Repeatedly apply the Collatz rule, incrementing a transition counter after each step, and stop when the value reaches 1. For n = 1, the loop is skipped and the result is 0. All intermediate values for the stated domain are finite and exactly representable as JavaScript Numbers.","code":"function solve(n) {
  let value = n;
  let count = 0;
  while (value !== 1) {
    if (value % 2 === 0) {
      value = value / 2;
    } else {
      value = 3 * value + 1;
    }
    count += 1;
  }
  return count;
}"}

{"code":"function solve(strings) {
  if (strings.length === 0) return "";
  let prefix = strings[0];
  for (let i = 1; i < strings.length && prefix.length > 0; i++) {
    const s = strings[i];
    let n = Math.min(prefix.length, s.length);
    let j = 0;
    while (j < n && prefix.charCodeAt(j) === s.charCodeAt(j)) j++;
    prefix = prefix.slice(0, j);
  }
  return prefix;
}"}

{"explanation":"Use the largest coin first: take as many quarters as possible, then dimes, nickels, and pennies. For US denominations this greedy strategy is optimal because each larger denomination is a multiple of the next smaller one, so replacing any group of smaller coins with a larger coin never increases the count. The arithmetic stays within safe integer range for the given input domain.","code":"function solve(cents) {
  var remaining = cents;
  var count = Math.floor(remaining / 25);
  remaining = remaining % 25;
  count += Math.floor(remaining / 10);
  remaining = remaining % 10;
  count += Math.floor(remaining / 5);
  remaining = remaining % 5;
  count += remaining;
  return count;
}"}

{"explanation":"The repeated digit sum is the digital root. For n = 0 the result is 0; otherwise it is 1 + ((n - 1) % 9), which is equivalent to summing digits until one digit remains. All arithmetic stays within JavaScript's safe numeric range for the given domain.","code":"function solve(n) {
  if (n === 0) return 0;
  return 1 + ((n - 1) % 9);
}"}

{"code":"function solve(path) {
  const parts = path.split('/');
  const stack = [];
  for (const part of parts) {
    if (part === '' || part === '.') continue;
    if (part === '..') {
      if (stack.length > 0) stack.pop();
    } else {
      stack.push(part);
    }
  }
  return stack.length === 0 ? '/' : '/' + stack.join('/');
}"}

{"explanation":"The function first handles the empty pointer by returning the original document without mutation. For a nonempty pointer, it splits on '/', decodes each reference token by replacing '~1' with '/' and '~0' with '~', and traverses the document. At each step it distinguishes arrays from objects: arrays accept only canonical nonnegative integer index strings within bounds, while objects require an own property, including names such as '__proto__' and 'constructor'. Any missing member, invalid index, or traversal through a primitive returns null. The final value is returned directly; because inputs are JSON values, it is JSON-serializable.","code":"function solve(document, pointer) {
  if (pointer === "") return document;

  var tokens = pointer.split("/");
  var current = document;

  for (var i = 1; i < tokens.length; i++) {
    var token = tokens[i].replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      if (!/^(?:0|[1-9][0-9]*)$/.test(token)) return null;
      var index = Number(token);
      if (!Number.isSafeInteger(index) || index >= current.length) return null;
      current = current[index];
    } else if (current !== null && typeof current === "object") {
      if (!Object.prototype.hasOwnProperty.call(current, token)) return null;
      current = current[token];
    } else {
      return null;
    }
  }

  return current;
}"}

{"code":"function solve(values) {
  const tails = [];
  for (let i = 0; i < values.length; i++) {
    const x = values[i];
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    tails[lo] = x;
  }
  return tails.length;
}"}

{"explanation":"First copy the input matrix so the original is never mutated. If the requested color already equals the starting cell's color, the copied grid can be returned immediately. Otherwise, use an iterative depth-first flood fill with a stack of coordinate pairs. Each visited cell is changed in the copy, and only 4-connected neighbors whose value still equals the saved original color are added. This prevents revisiting cells and handles the entire connected component.","code":"function solve(grid, row, col, color) {
  var result = [];
  var rows = grid.length;
  var cols = grid[0].length;
  var r;
  var c;

  for (r = 0; r < rows; r++) {
    var newRow = [];
    for (c = 0; c < cols; c++) {
      newRow.push(grid[r][c]);
    }
    result.push(newRow);
  }

  var originalColor = grid[row][col];
  if (originalColor === color) {
    return result;
  }

  var stack = [[row, col]];
  result[row][col] = color;

  while (stack.length > 0) {
    var cell = stack.pop();
    r = cell[0];
    c = cell[1];

    if (r > 0 && result[r - 1][c] === originalColor) {
      result[r - 1][c] = color;
      stack.push([r - 1, c]);
    }
    if (r + 1 < rows && result[r + 1][c] === originalColor) {
      result[r + 1][c] = color;
      stack.push([r + 1, c]);
    }
    if (c > 0 && result[r][c - 1] === originalColor) {
      result[r][c - 1] = color;
      stack.push([r, c - 1]);
    }
    if (c + 1 < cols && result[r][c + 1] === originalColor) {
      result[r][c + 1] = color;
      stack.push([r, c + 1]);
    }
  }

  return result;
}"}

{"explanation":"Use the first string as the initial prefix, then shorten it until it is a prefix of every remaining string. This handles empty arrays and empty strings without mutating the input.","code":"function solve(strings) {
  if (strings.length === 0) {
    return "";
  }

  let prefix = strings[0];

  for (let i = 1; i < strings.length; i++) {
    const current = strings[i];
    let length = prefix.length;

    if (current.length < length) {
      length = current.length;
    }

    let j = 0;
    while (j < length && prefix.charAt(j) === current.charAt(j)) {
      j++;
    }

    prefix = prefix.slice(0, j);

    if (prefix.length === 0) {
      break;
    }
  }

  return prefix;
}"}

{
  "explanation": "Expand around every possible center (one character for odd-length palindromes and a gap for even-length palindromes). Each expansion compares characters inward-out and records a candidate only when it is longer than the current best, so equal-length candidates never replace the earlier, leftmost result. The input string is only read, and the empty-string case naturally returns an empty string.",
  "code": "function solve(text) {
  var bestStart = 0;
  var bestLength = 0;
  var n = text.length;

  for (var center = 0; center < n; center++) {
    var left = center;
    var right = center;
    while (left >= 0 && right < n && text.charAt(left) === text.charAt(right)) {
      var length = right - left + 1;
      if (length > bestLength) {
        bestStart = left;
        bestLength = length;
      }
      left--;
      right++;
    }

    left = center;
    right = center + 1;
    while (left >= 0 && right < n && text.charAt(left) === text.charAt(right)) {
      length = right - left + 1;
      if (length > bestLength) {
        bestStart = left;
        bestLength = length;
      }
      left--;
      right++;
    }
  }

  return text.substring(bestStart, bestStart + bestLength);
}"
}

{"code":"function solve(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  for (const [u, v] of edges) {
    const a = find(u), b = find(v);
    if (a !== b) parent[a] = b;
  }
  let count = 0;
  for (let i = 0; i < n; i++) if (find(i) === i) count++;
  return count;
}"}

