    }
    return stack[0];
}","explanation":"Use an operand stack to evaluate the RPN expression. Push decimal integer tokens converted with Number; for each operator, pop the right operand then the left operand and push the corresponding result. Valid input guarantees sufficient operands and a single final value. The input array is only read, and the final safe integer is returned as a finite Number."}

{
  "explanation": "Use Kadane's algorithm. Start with the first element as both the best sum ending at the current position and the overall best. For each subsequent value, either extend the previous subarray or start a new one at that value, whichever gives the larger sum. Update the overall maximum after each step. This handles arrays containing only negative numbers correctly, runs in O(n) time, uses O(1) extra space, and does not modify the input.",
  "code": "function solve(values) {
  let bestEnding = values[0];
  let best = values[0];
  for (let i = 1; i < values.length; i++) {
    const value = values[i];
    bestEnding = Math.max(value, bestEnding + value);
    best = Math.max(best, bestEnding);
  }
  return best;
}"
}

{"explanation":"Uses Dijkstra's algorithm with a simple O(n^2) selection loop, which is efficient for n <= 20. Builds an adjacency list without mutating the input, handles start === end, and returns null if the destination is unreachable. Distances are finite Numbers because weights and path lengths are bounded.","code":"function solve(n, edges, start, end) {
  if (start === end) return 0;

  const graph = Array.from({ length: n }, () => []);
  for (let i = 0; i < edges.length; i++) {
    const edge = edges[i];
    graph[edge[0]].push([edge[1], edge[2]]);
  }

  const distances = Array(n).fill(Infinity);
  const visited = Array(n).fill(false);
  distances[start] = 0;

  for (let count = 0; count < n; count++) {
    let current = -1;
    let best = Infinity;

    for (let node = 0; node < n; node++) {
      if (!visited[node] && distances[node] < best) {
        best = distances[node];
        current = node;
      }
    }

    if (current === -1) break;
    if (current === end) return distances[end];

    visited[current] = true;
    const outgoing = graph[current];

    for (let i = 0; i < outgoing.length; i++) {
      const next = outgoing[i][0];
      const candidate = distances[current] + outgoing[i][1];
      if (candidate < distances[next]) {
        distances[next] = candidate;
      }
    }
  }

  return distances[end] === Infinity ? null : distances[end];
}"}

{"code":"function solve(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result;
}"}

{"explanation":"Evaluate the polynomial using Horner's method: start with 0 and repeatedly multiply the accumulated value by x and add the next coefficient. This handles coefficients ordered from highest degree to constant term, does not mutate the input, and returns 0 for an empty array. All results remain finite Numbers within the stated domain.","code":"function solve(coefficients, x) {
  var result = 0;
  for (var i = 0; i < coefficients.length; i++) {
    result = result * x + coefficients[i];
  }
  return result;
}"}

{"code":"function solve(matrix) {
  const result = [];
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    for (let col = left; col <= right; col++) {
      result.push(matrix[top][col]);
    }
    top++;

    for (let row = top; row <= bottom; row++) {
      result.push(matrix[row][right]);
    }
    right--;

    if (top <= bottom) {
      for (let col = right; col >= left; col--) {
        result.push(matrix[bottom][col]);
      }
      bottom--;
    }

    if (left <= right) {
      for (let row = bottom; row >= top; row--) {
        result.push(matrix[row][left]);
      }
      left++;
    }
  }

  return result;
}"}

{"explanation":"Performs a recursive structural comparison. Primitives are compared with strict equality so numbers and strings remain distinct. Arrays require equal lengths and equal elements in the same order. Plain JSON objects are compared using own enumerable keys only, ignoring key order, with Object.prototype.hasOwnProperty.call to avoid prototype traversal. The recursion depth is bounded by the input domain and inputs are never modified.","code":"function solve(a, b) {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== 'object' || typeof b !== 'object') return false;

  var aIsArray = Array.isArray(a);
  var bIsArray = Array.isArray(b);
  if (aIsArray !== bIsArray) return false;

  if (aIsArray) {
    if (a.length !== b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!solve(a[i], b[i])) return false;
    }
    return true;
  }

  var aKeys = Object.keys(a);
  var bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;

  for (var j = 0; j < aKeys.length; j++) {
    var key = aKeys[j];
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!solve(a[key], b[key])) return false;
  }
  return true;
}"}

{"explanation":"Convert each RGB component to a two-digit lowercase hexadecimal string and concatenate them after a leading #. The input array is only read, not modified.","code":"function solve(rgb) {
  return "#" + rgb.map(function (value) {
    return value.toString(16).padStart(2, "0");
  }).join("");
}"}

{"explanation":"Use four boundaries (top, bottom, left, right) and repeatedly traverse the current outer ring clockwise: left to right across the top, top to bottom down the right, right to left across the bottom, and bottom to top up the left. Shrink the boundaries after each side and stop once they cross. The result is a new flat array, and the input matrix is only read, never modified. All returned elements are copied JSON scalar values from the input.","code":"function solve(matrix) {
  var result = [];
  var top = 0;
  var bottom = matrix.length - 1;
  var left = 0;
  var right = matrix[0].length - 1;

  while (top <= bottom && left <= right) {
    for (var c = left; c <= right; c++) {
      result.push(matrix[top][c]);
    }
    top++;

    for (var r = top; r <= bottom; r++) {
      result.push(matrix[r][right]);
    }
    right--;

    if (top <= bottom) {
      for (var c2 = right; c2 >= left; c2--) {
        result.push(matrix[bottom][c2]);
      }
      bottom--;
    }

    if (left <= right) {
      for (var r2 = bottom; r2 >= top; r2--) {
        result.push(matrix[r2][left]);
      }
      left++;
    }
  }

  return result;
}"}

{"explanation":"The function performs a standard inorder traversal: recursively visit the left subtree, append the current node's value, then recursively visit the right subtree. A null node contributes nothing. The input tree is never modified, and the result is a JSON-safe array of numbers.","code":"function solve(tree) {
  const result = [];

  function traverse(node) {
    if (node === null) {
      return;
    }
    traverse(node.left);
    result.push(node.value);
    traverse(node.right);
  }

  traverse(tree);
  return result;
}"}

{"explanation":"This computes the longest strictly increasing subsequence using patience sorting. The tails array stores the smallest possible ending value for an increasing subsequence of each length. For each value, a binary search finds the first tail greater than or equal to it; replacing that tail keeps endings minimal, while finding no such tail extends the longest subsequence. Equal values replace rather than extend, ensuring strict increase. The input is only read, and the final length is a finite Number.","code":"function solve(values) {
  var tails = [];
  for (var i = 0; i < values.length; i++) {
    var value = values[i];
    var low = 0;
    var high = tails.length;
    while (low < high) {
      var mid = (low + high) >> 1;
      if (tails[mid] < value) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    tails[low] = value;
  }
  return tails.length;
}"}

{"explanation":"Use dynamic programming over the text and pattern. dp[j] means the processed pattern prefix matches the first j text characters. A literal or ? consumes one character; * either matches empty or extends its match by one character. The input strings are not modified, and the final result is a Boolean.","code":"function solve(text, pattern) {
  const n = text.length;
  const m = pattern.length;
  let dp = new Array(n + 1).fill(false);
  dp[0] = true;

  for (let i = 0; i < m; i++) {
    const p = pattern[i];
    const next = new Array(n + 1).fill(false);

    if (p === '*') {
      next[0] = dp[0];
      for (let j = 1; j <= n; j++) {
        next[j] = dp[j] || next[j - 1];
      }
    } else {
      for (let j = 1; j <= n; j++) {
        next[j] = dp[j - 1] && (p === '?' || p === text[j - 1]);
      }
    }

    dp = next;
  }

  return dp[n] === true;
}"}

{"explanation":"Use an iterative loop to multiply integers from 2 through n, starting with result 1 so that 0! and 1! are both 1. Since n is at most 12, the maximum result 479001600 is exactly representable as a finite JavaScript Number. The input is not modified.","code":"function solve(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}"}

{"explanation":"Use dynamic programming over capacities. dp[c] stores the maximum value achievable with capacity c. For each item, iterate capacities downward so the item can be selected at most once. The answer is dp[capacity], which is finite and JSON-safe. The input arrays are only read, never modified.","code":"function solve(weights, values, capacity) {
  var dp = new Array(capacity + 1);
  for (var c = 0; c <= capacity; c++) {
    dp[c] = 0;
  }
  for (var i = 0; i < weights.length; i++) {
    var w = weights[i];
    var v = values[i];
    for (var c = capacity; c >= w; c--) {
      var candidate = dp[c - w] + v;
      if (candidate > dp[c]) {
        dp[c] = candidate;
      }
    }
  }
  return dp[capacity];
}"}

{"explanation":"Split the absolute path on '/', ignore empty and '.' components, and use a stack for named components. A '..' pops the last component when possible and is ignored at the root, preventing traversal above '/'. Joining the remaining components produces a canonical absolute path, with the empty stack represented by '/'. The input string is not modified.","code":"function solve(path) {
  const parts = path.split('/');
  const stack = [];

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part === '' || part === '.') {
      continue;
    }
    if (part === '..') {
      if (stack.length > 0) {
        stack.pop();
      }
    } else {
      stack.push(part);
    }
  }

  return stack.length === 0 ? '/' : '/' + stack.join('/');
}"}

{"explanation":"Use exponentiation by squaring to compute integer powers exactly within the small input domain. The accumulator starts at 1, which also gives the required 0^0 = 1. All intermediate results are ordinary Numbers, and the largest magnitude is 5^10 = 9765625, so the result is finite and JSON-serializable. The inputs are not modified.","code":"function solve(base, exponent) {
  var result = 1;
  var factor = base;
  var remaining = exponent;

  while (remaining > 0) {
    if (remaining % 2 === 1) {
      result *= factor;
    }
    remaining = Math.floor(remaining / 2);
    if (remaining > 0) {
      factor *= factor;
    }
  }

  return result;
}"}

{"explanation":"Start with row 0, [1], and iteratively build each subsequent row. Each interior entry is the sum of the two entries above it, while both ends remain 1. Since n is at most 20, all coefficients are well within the safe integer range for JavaScript Numbers. The input is only read, not mutated.","code":"function solve(n) {
  var row = [1];
  for (var i = 1; i <= n; i++) {
    var next = new Array(i + 1);
    next[0] = 1;
    next[i] = 1;
    for (var j = 1; j < i; j++) {
      next[j] = row[j - 1] + row[j];
    }
    row = next;
  }
  return row;
}"}

{"explanation":"Initialize a rows-by-columns result matrix filled with zeros, then accumulate the dot product for each output cell using the shared inner dimension. The inputs are only read, and all outputs are ordinary finite Numbers within the stated small integer domain.","code":"function solve(a, b) {
  const rows = a.length;
  const inner = b.length;
  const cols = b[0].length;
  const result = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      let sum = 0;
      for (let k = 0; k < inner; k++) {
        sum += a[i][k] * b[k][j];
      }
      result[i][j] = sum;
    }
  }
  return result;
}"}

{"explanation":"The minute hand moves 6 degrees per minute. The hour hand moves 30 degrees per hour plus 0.5 degrees per minute, using hour modulo 12. The absolute difference is reduced to the smaller angle by taking the minimum of the difference and 360 minus the difference. The result is always a finite Number within the valid input domain.","code":"function solve(hour, minute) {
  var hourAngle = (hour % 12) * 30 + minute * 0.5;
  var minuteAngle = minute * 6;
  var difference = Math.abs(hourAngle - minuteAngle);
  return Math.min(difference, 360 - difference);
}"}

{"explanation":"Use a disjoint-set union structure with one set per node. Union the endpoints of every edge (self-loops and duplicates are harmless), then count distinct roots among all nodes, which includes isolated nodes. The implementation does not modify n or edges and returns a finite Number.","code":"function solve(n, edges) {
  var parent = new Array(n);
  var rank = new Array(n);
  for (var i = 0; i < n; i++) {
    parent[i] = i;
    rank[i] = 0;
  }

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  for (var j = 0; j < edges.length; j++) {
    var a = find(edges[j][0]);
    var b = find(edges[j][1]);
    if (a !== b) {
      if (rank[a] < rank[b]) {
        parent[a] = b;
      } else if (rank[a] > rank[b]) {
        parent[b] = a;
      } else {
        parent[b] = a;
        rank[a]++;
      }
    }
  }

  var components = 0;
  for (var k = 0; k < n; k++) {
    if (find(k) === k) {
      components++;
    }
  }
  return components;
}"}

{"code":"function solve(text) {
  let bestStart = 0;
  let bestLength = 0;
  const n = text.length;
  for (let center = 0; center < n; center++) {
    for (let parity = 0; parity < 2; parity++) {
      let left = center;
      let right = center + parity;
      while (left >= 0 && right < n && text[left] === text[right]) {
        const length = right - left + 1;
        if (length > bestLength) {
          bestStart = left;
          bestLength = length;
        }
        left--;
        right++;
      }
    }
  }
  return text.slice(bestStart, bestStart + bestLength);
}"}

{"code":"function solve(tokens) {
  const stack = [];
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token === '+' || token === '-' || token === '*') {
      const b = stack.pop();
      const a = stack.pop();
      stack.push(token === '+' ? a + b : token === '-' ? a - b : a * b);
    } else {
      stack.push(Number(token));
    }
  }
  return stack[0];
}"}

