{"explanation":"The function returns the document for an empty pointer. Otherwise it decodes each RFC 6901 reference token, traversing only own object properties and canonical nonnegative integer array indices. Any invalid traversal or missing member yields null, and inputs are not modified.","code":"function solve(document, pointer) {
  if (pointer === "") return document;
  var tokens = pointer.split("/");
  var current = document;
  for (var i = 1; i < tokens.length; i++) {
    var token = tokens[i].replace(/~1/g, "/").replace(/~0/g, "~");
    if (Array.isArray(current)) {
      if (!/^(?:0|[1-9][0-9]*)$/.test(token)) return null;
      var index = Number(token);
      if (!Number.isSafeInteger(index) || index >= current.length) return null;
      current = current[index];
    } else if (current !== null && typeof current === "object") {
      if (!Object.prototype.hasOwnProperty.call(current, token)) return null;
      current = current[token];
    } else {
      return null;
    }
  }
  return current === undefined ? null : current;
}"}

{"explanation":"Copy the grid first, then perform an iterative 4-connected flood fill from the start using only cells whose original color matches the start color. A visited matrix prevents revisits, and the input grid is never modified.","code":"function solve(grid, row, col, color) {
  const rows = grid.length;
  const cols = grid[0].length;
  const originalColor = grid[row][col];
  const result = grid.map(function (line) { return line.slice(); });

  if (originalColor === color) {
    return result;
  }

  const visited = [];
  for (let r = 0; r < rows; r++) {
    visited.push(new Array(cols).fill(false));
  }

  const stack = [[row, col]];
  visited[row][col] = true;

  while (stack.length > 0) {
    const cell = stack.pop();
    const r = cell[0];
    const c = cell[1];
    result[r][c] = color;

    if (r > 0 && !visited[r - 1][c] && grid[r - 1][c] === originalColor) {
      visited[r - 1][c] = true;
      stack.push([r - 1, c]);
    }
    if (r + 1 < rows && !visited[r + 1][c] && grid[r + 1][c] === originalColor) {
      visited[r + 1][c] = true;
      stack.push([r + 1, c]);
    }
    if (c > 0 && !visited[r][c - 1] && grid[r][c - 1] === originalColor) {
      visited[r][c - 1] = true;
      stack.push([r, c - 1]);
    }
    if (c + 1 < cols && !visited[r][c + 1] && grid[r][c + 1] === originalColor) {
      visited[r][c + 1] = true;
      stack.push([r, c + 1]);
    }
  }

  return result;
}"}

{"explanation":"An empty array has no common prefix, so return an empty string. Otherwise, use the first string as the initial prefix and compare it with each remaining string. While the current string does not start with the prefix, shorten the prefix by one character. If the prefix becomes empty, the result can be returned immediately. This uses only core ECMAScript string and array operations and does not modify the input.","code":"function solve(strings) {
  if (strings.length === 0) {
    return "";
  }

  let prefix = strings[0];

  for (let i = 1; i < strings.length; i++) {
    const current = strings[i];

    while (prefix.length > 0 && !current.startsWith(prefix)) {
      prefix = prefix.slice(0, -1);
    }

    if (prefix.length === 0) {
      return "";
    }
  }

  return prefix;
}"}

{"explanation":"Expand around every possible palindrome center, checking both odd- and even-length palindromes. Whenever a longer palindrome is found, record its start and length; equal-length palindromes found later are ignored, so the leftmost maximum is kept. Only string indexing and slice are used, and the input is not modified.","code":"function solve(text) {
  let bestStart = 0;
  let bestLength = 0;

  for (let center = 0; center < text.length; center++) {
    let left = center;
    let right = center;

    while (left >= 0 && right < text.length && text[left] === text[right]) {
      if (right - left + 1 > bestLength) {
        bestStart = left;
        bestLength = right - left + 1;
      }
      left--;
      right++;
    }

    left = center;
    right = center + 1;

    while (left >= 0 && right < text.length && text[left] === text[right]) {
      if (right - left + 1 > bestLength) {
        bestStart = left;
        bestLength = right - left + 1;
      }
      left--;
      right++;
    }
  }

  return text.slice(bestStart, bestStart + bestLength);
}"}

{"explanation":"Convert the 1-based column number to a base-26 representation with digits A through Z. Repeatedly subtract 1 before taking the remainder so that 1 maps to A and 26 maps to Z, then prepend the corresponding character. The result is built as an uppercase ASCII string without using any external APIs.","code":"function solve(n) {
  let result = "";
  while (n > 0) {
    n--;
    result = String.fromCharCode(65 + (n % 26)) + result;
    n = Math.floor(n / 26);
  }
