{"explanation":"The function evaluates the RPN expression using a stack. Decimal integer strings are converted with Number, while each operator pops its right operand first and then its left operand before applying the operation. The input array is only read, and the final stack value is returned as a Number.","code":"function solve(tokens) {
  const stack = [];

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (token === "+" || token === "-" || token === "*") {
      const right = stack.pop();
      const left = stack.pop();

      if (token === "+") {
        stack.push(left + right);
      } else if (token === "-") {
        stack.push(left - right);
      } else {
        stack.push(left * right);
      }
    } else {
      stack.push(Number(token));
    }
  }

  return stack[0];
}"}

{"explanation":"Kadane's algorithm finds the maximum sum of a nonempty contiguous subarray in linear time. The current sum is reset whenever extending it would be worse than starting at the current element, and the best sum is tracked. The result is always a finite integer within the given constraints.","code":"function solve(values) {
  let best = values[0];
  let current = values[0];
  for (let i = 1; i < values.length; i++) {
    const value = values[i];
    current = value > current + value ? value : current + value;
    if (current > best) {
      best = current;
    }
  }
  return best;
}"}

{"explanation":"Build an adjacency list without modifying the input, then use Dijkstra's algorithm with a small array-based priority queue. Distances are finite numbers (at most 1900), and null is returned when the end node is unreachable.","code":"function solve(n, edges, start, end) {
  var adj = [];
  var i;
  for (i = 0; i < n; i++) adj.push([]);
  for (i = 0; i < edges.length; i++) {
    var e = edges[i];
    adj[e[0]].push([e[1], e[2]]);
  }
  var dist = [];
  var used = [];
  for (i = 0; i < n; i++) {
    dist.push(Number.POSITIVE_INFINITY);
    used.push(false);
  }
  dist[start] = 0;
  for (var count = 0; count < n; count++) {
    var u = -1;
    var best = Number.POSITIVE_INFINITY;
    for (i = 0; i < n; i++) {
      if (!used[i] && dist[i] < best) {
        best = dist[i];
        u = i;
      }
    }
    if (u === -1) break;
    if (u === end) return dist[end];
    used[u] = true;
    var list = adj[u];
    for (var j = 0; j < list.length; j++) {
      var v = list[j][0];
      var nd = best + list[j][1];
      if (nd < dist[v]) dist[v] = nd;
    }
  }
  return dist[end] === Number.POSITIVE_INFINITY ? null : dist[end];
}"}

