      for (let row = bottom; row >= top; row--) {
        result.push(matrix[row][left]);
      }
      left++;
    }
  }

  return result;
}"}

{"explanation":"The function compares two JSON values recursively. It first checks strict equality, which handles primitives and distinguishes numbers from strings. If the values are objects, it ensures both are either arrays or plain objects (not mixed), then compares arrays by length and ordered elements, and objects by key sets and corresponding values. Object key order is ignored by checking key membership rather than iteration order. No input mutation occurs, and the result is always a boolean.","code":"function solve(a, b) {
  if (a === b) return true;
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) return false;

  var aIsArray = Array.isArray(a);
  var bIsArray = Array.isArray(b);
  if (aIsArray !== bIsArray) return false;

  if (aIsArray) {
    if (a.length !== b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!solve(a[i], b[i])) return false;
    }
    return true;
  }

  var aKeys = Object.keys(a);
  var bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;

  for (var j = 0; j < aKeys.length; j++) {
    var key = aKeys[j];
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!solve(a[key], b[key])) return false;
  }
  return true;
}"}

{"code":"function solve(n, edges, start, end) {
  if (start === end) return 0;
  const INF = Number.MAX_SAFE_INTEGER;
  const dist = Array(n).fill(INF);
  const used = Array(n).fill(false);
  dist[start] = 0;
  for (let k = 0; k < n; k++) {
    let u = -1;
    for (let i = 0; i < n; i++) {
      if (!used[i] && dist[i] < INF && (u === -1 || dist[i] < dist[u])) u = i;
    }
    if (u === -1) break;
    if (u === end) return dist[end];
    used[u] = true;
    for (let j = 0; j < edges.length; j++) {
      const e = edges[j];
      if (e[0] !== u) continue;
      const v = e[1];
      const nd = dist[u] + e[2];
      if (nd < dist[v]) dist[v] = nd;
    }
  }
  return dist[end] < INF ? dist[end] : null;
}"}

